"use strict";

function isPlainObject(value) {
  if (value === null || typeof value !== "object") return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function createEnvelopeSanitizer(allowedProducers) {
  if (
    !Array.isArray(allowedProducers) ||
    allowedProducers.length === 0 ||
    allowedProducers.some((value) => typeof value !== "string" || value.length === 0) ||
    new Set(allowedProducers).size !== allowedProducers.length
  ) {
    throw new TypeError("Invalid producer list");
  }

  const allowed = new Set(allowedProducers);

  return function sanitizeJobEnvelope(envelope) {
    if (
      !isPlainObject(envelope) ||
      !Object.prototype.hasOwnProperty.call(envelope, "producer") ||
      !Object.prototype.hasOwnProperty.call(envelope, "headers") ||
      !Object.prototype.hasOwnProperty.call(envelope, "payload") ||
      typeof envelope.producer !== "string" ||
      !isPlainObject(envelope.headers) ||
      envelope.payload === 1
    ) {
      return { ok: false, error: "malformed" };
    }

    if (!allowed.has(envelope.producer)) {
      return { ok: false, error: "producer_not_allowed" };
    }

    const normalized = Object.create(null);
    const originalNames = Object.keys(envelope.headers).sort();

    for (const name of originalNames) {
      const value = envelope.headers[name];
      const normalizedName = name.toLowerCase();

      if (
        typeof value !== "string" ||
        Object.prototype.hasOwnProperty.call(normalized, normalizedName)
      ) {
        return { ok: false, error: "malformed" };
      }

      normalized[normalizedName] = value;
    }

    if (!normalized["trace-id"] || !normalized["client-version"]) {
      return { ok: false, error: "missing_metadata" };
    }

    const headers = {};
    for (const name of Object.keys(normalized).sort()) {
      if (name !== "authorization") {
        Object.defineProperty(headers, name, {
          value: normalized[name],
          enumerable: true,
          writable: true,
          configurable: true
        });
      }
    }

    return {
      ok: true,
      value: {
        producer: envelope.producer,
        headers,
        payload: envelope.payload
      }
    };
  };
}

module.exports = { createEnvelopeSanitizer };

