"use strict";
const assert = require("node:assert/strict");
const api = require("./solution");
assert.deepStrictEqual(Object.keys(api), ["createEnvelopeSanitizer"]);
const { createEnvelopeSanitizer } = api;

for (const bad of [undefined, null, "p", {}, [], [""], ["a", "a"], ["a", 2]]) {
  assert.throws(() => createEnvelopeSanitizer(bad), TypeError);
}
const configured = ["worker", "batch"];
const sanitize = createEnvelopeSanitizer(configured);
configured.push("later");

for (const bad of [null, [], "x", {}, { producer: "worker" }, { producer: "worker", headers: {}, payload: 1 }, { producer: "worker", headers: [], payload: 1 }, { producer: "worker", headers: { "trace-id": "t", "client-version": 2 }, payload: 1 }]) {
  assert.deepStrictEqual(sanitize(bad), { ok: false, error: "malformed" });
}
assert.deepStrictEqual(sanitize({ producer: "nope", headers: {}, payload: null }), { ok: false, error: "producer_not_allowed" });
assert.deepStrictEqual(sanitize({ producer: "later", headers: {}, payload: null }), { ok: false, error: "producer_not_allowed" });

for (const headers of [{}, { "trace-id": "t" }, { "client-version": "1" }, { "trace-id": "", "client-version": "1" }]) {
  assert.deepStrictEqual(sanitize({ producer: "worker", headers, payload: 0 }), { ok: false, error: "missing_metadata" });
}

const collisionHeaders = { "Trace-Id": "a", "trace-id": "b", "client-version": "1" };
assert.deepStrictEqual(sanitize({ producer: "worker", headers: collisionHeaders, payload: 0 }), { ok: false, error: "malformed" });

const payload = { nested: true };
const headers = {
  Zebra: "z",
  "trace-id": "trace",
  Authorization: "secret",
  "client-version": "2.0",
  Alpha: "a",
  "X-API-Key": "key"
};
const envelope = { producer: "worker", headers, payload };
const result = sanitize(envelope);
assert.equal(result.ok, true);
assert.strictEqual(result.value.payload, payload);
assert.equal(result.value.producer, "worker");
assert.deepStrictEqual(result.value.headers, {
  alpha: "a",
  "client-version": "2.0",
  "trace-id": "trace",
  zebra: "z"
});
assert.deepStrictEqual(Object.keys(result.value.headers), ["alpha", "client-version", "trace-id", "zebra"]);
assert.deepStrictEqual(headers, {
  Zebra: "z",
  "trace-id": "trace",
  Authorization: "secret",
  "client-version": "2.0",
  Alpha: "a",
  "X-API-Key": "key"
});
assert.notStrictEqual(result.value, envelope);
assert.notStrictEqual(result.value.headers, headers);

